[CmdletBinding()] param([switch]$Install,[switch]$Uninstall,[switch]$Start,[switch]$Stop,[switch]$Restart,[switch]$DryRun)
. "$PSScriptRoot/common.ps1"; if(-not $DryRun){Assert-Admin}
$svc=$Script:ServiceName; $apiRoot=Join-Path $Script:DeployRoot "apps\api"; $exe=Join-Path $apiRoot ".venv\Scripts\python.exe"; $app=(Get-Setting "WEB_APP_MODULE" "app.main:app"); $args="-m uvicorn $app --host $Script:ApiHost --port $Script:ApiPort"
if($Install){Invoke-Step "Install service $svc" { if(Test-Path $Script:WinSW){Copy-Item $Script:WinSW (Join-Path $Script:DeployRoot "$svc.exe") -Force; $xml="<service><id>$svc</id><name>$svc</name><executable>$exe</executable><arguments>$args</arguments><workingdirectory>$apiRoot</workingdirectory><log mode='roll-by-size'/><onfailure action='restart'/></service>"; Set-Content (Join-Path $Script:DeployRoot "$svc.xml") $xml; & (Join-Path $Script:DeployRoot "$svc.exe") install} elseif(Get-Command nssm -ErrorAction SilentlyContinue){& nssm install $svc $exe $args; & nssm set $svc AppDirectory $Script:DeployRoot} else {throw "Place winsw.exe beside this script or install NSSM."} } $DryRun}
if($Uninstall){Invoke-Step "Uninstall service $svc" {if(Test-Path (Join-Path $Script:DeployRoot "$svc.exe")){& (Join-Path $Script:DeployRoot "$svc.exe") uninstall}elseif(Get-Command nssm -ErrorAction SilentlyContinue){& nssm remove $svc confirm}else{sc.exe delete $svc}} $DryRun}
if($Start){Invoke-Step "Start service" {Start-Service $svc} $DryRun}; if($Stop){Invoke-Step "Stop service" {Stop-Service $svc} $DryRun}; if($Restart){Invoke-Step "Restart service" {Restart-Service $svc} $DryRun}
